 "content": "def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    bg = max(set(v for row in g for v in row), key=lambda x: sum(row.count(x) for row in g))
    def find_bar(r):
        for c in range(w - 2):
            if g[r][c] != bg and g[r][c] == g[r][c + 1] == g[r][c + 2]:
                return c
        return None
    top, bottom = find_bar(0), find_bar(h - 1)
    if top is None or bottom is None:
        return g
    shift = bottom - top
    points = [(r, c, g[r][c]) for r in range(1, h - 1) for c in range(w) if g[r][c] != bg]
    for r, c, color in points:
        for rr in range(1, r):
            g[rr][c] = color
        other = c + shift
        if 0 <= other < w:
            for rr in range(h - 1):
                g[rr][other] = color
        g[r][c] = 4
    return g
