 "content": "def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    counts = {}
    for row in g:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)

    def edge_bar(row_index):
        row = g[row_index]
        for c in range(w - 2):
            if row[c] != background and row[c] == row[c + 1] == row[c + 2]:
                return c, row[c]
        return None

    top = edge_bar(0)
    bottom = edge_bar(h - 1)
    if top is None or bottom is None:
        return g
    top_col, border_color = top
    bottom_col, _ = bottom
    shift = bottom_col - top_col

    # Every isolated interior non-background cell projects two vertical rays:
    # through its own column and the corresponding shifted column. The marker
    # itself becomes 4; the three-cell edge bars remain untouched.
    markers = [(r, c, g[r][c]) for r in range(1, h - 1)
               for c in range(w) if g[r][c] != background]
    for r, c, color in markers:
        for rr in range(h):
            for cc in (c, c + shift):
                if not (0 <= cc < w):
                    continue
                # Do not overwrite either edge bar.
                if (rr == 0 or rr == h - 1) and g[rr][cc] == border_color:
                    continue
                g[rr][cc] = color
        g[r][c] = 4
    return g
