    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    counts = {}
    for row in g:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)

    def find_bar(r):
        for c in range(w - 2):
            if g[r][c] != background and g[r][c] == g[r][c + 1] == g[r][c + 2]:
                return c, g[r][c]
        return None

    top = find_bar(0)
    bottom = find_bar(h - 1)
    if top is None or bottom is None:
        return g
    top_col, top_color = top
    bottom_col, bottom_color = bottom
    delta = bottom_col - top_col

    markers = [(r, c, g[r][c]) for r in range(1, h - 1)
               for c in range(w) if g[r][c] != background]
    for r, c, color in markers:
        translated_col = c + delta
        # Draw the original marker's vertical line toward the nearer edge bar.
        if r < (h - 1) // 2:
            rows = range(r + 1, h - 1)
        else:
            rows = range(1, r)
        for rr in rows:
            g[rr][c] = color
        # Draw a second line in the translated column from the opposite edge.
        if 0 <= translated_col < w:
            if r < (h - 1) // 2:
                rows = range(1, h - 1)
            else:
                rows = range(1, r)
            for rr in rows:
                g[rr][translated_col] = color
        g[r][c] = 4
    return g
