    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    counts = {}
    for row in g:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)

    def edge_bar(row):
        # The edge object is the non-background contiguous run (at least 3 cells).
        nz = [i for i, v in enumerate(row) if v != bg]
        if not nz:
            return None
        return min(nz), max(nz)

    top = edge_bar(g[0])
    bottom = edge_bar(g[-1])
    if top is None or bottom is None:
        return g
    t0, t1 = top
    b0, b1 = bottom

    points = [(r, c, g[r][c]) for r in range(1, h - 1)
              for c in range(w) if g[r][c] != bg]
    for r, c, color in points:
        if t0 <= c <= t1:
            # Marker is aligned with the top edge object: extend upward.
            other = c + (b0 - t0)
            for rr in range(0, r):
                if g[rr][c] == bg:
                    g[rr][c] = color
        elif b0 <= c <= b1:
            # Marker is aligned with the bottom edge object: extend downward.
            other = c + (t0 - b0)
            for rr in range(r + 1, h):
                if g[rr][c] == bg:
                    g[rr][c] = color
        else:
            # Fallback for points outside both edge-bar spans: use the nearest
            # span and its corresponding displacement.
            if abs(c - (t0 + t1) / 2) <= abs(c - (b0 + b1) / 2):
                other = c + (b0 - t0)
                for rr in range(0, r):
                    if g[rr][c] == bg:
