            else:
                other = c + (t0 - b0)
                for rr in range(r + 1, h):
                    if g[rr][c] == bg:
                        g[rr][c] = color
        # The corresponding vertical line spans the grid; preserve edge bars.
        if 0 <= other < w:
            for rr in range(h):
                if g[rr][other] == bg:
                    g[rr][other] = color

    for r, c, _ in points:
        g[r][c] = 4
