 "content": "def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])

    # The most frequent color is the background.
    counts = {}
    for row in g:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)

    def edge_bar(row):
        cols = [c for c, value in enumerate(row) if value != background]
        if not cols:
            return None
        return min(cols), max(cols)

    top = edge_bar(g[0])
    bottom = edge_bar(g[-1])
    if top is None or bottom is None:
        return g
    top_start, top_end = top
    bottom_start, bottom_end = bottom

    markers = [(r, c, g[r][c]) for r in range(1, h - 1)
               for c in range(w) if g[r][c] != background]

    for r, c, color in markers:
        # Associate each marker with the nearer edge bar horizontally.
        top_distance = max(top_start - c, 0, c - top_end)
        bottom_distance = max(bottom_start - c, 0, c - bottom_end)
        if top_distance <= bottom_distance:
            own_start = top_start
            other_start = bottom_start
            toward_top = True
        else:
            own_start = bottom_start
            other_start = top_start
            toward_top = False

        # Continue the original marker column toward its associated edge.
        if toward_top:
            for rr in range(1, r):
                g[rr][c] = color
        else:
            for rr in range(r + 1, h - 1):
                g[rr][c] = color

        # Copy the marker's column to the aligned position at the opposite
        # edge bar, extending that copied line through the interior.
        partner = c + (other_start - own_start)
        if 0 <= partner < w:
            for rr in range(1, h - 1):
                g[rr][partner] = color

        g[r][c] = 4

    return g
"
