    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    counts = {}
    for row in g:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    bg = max(counts, key=counts.get)

    def span(row):
        cs = [c for c, v in enumerate(row) if v != bg]
        return (min(cs), max(cs)) if cs else None

    top = span(g[0])
    bottom = span(g[-1])
    if top is None or bottom is None:
        return g
    top_start, top_end = top
    bottom_start, bottom_end = bottom
    markers = [(r, c, g[r][c]) for r in range(1, h - 1)
               for c in range(w) if g[r][c] != bg]

    for r, c, color in markers:
        dt = max(top_start - c, 0, c - top_end)
        db = max(bottom_start - c, 0, c - bottom_end)
        if dt <= db:
            # Top-side marker: extend its column upward; the translated column
            # runs down the grid from the marker level.
            partner = c + (bottom_start - top_start)
            for rr in range(1, r):
                g[rr][c] = color
            if 0 <= partner < w:
                for rr in range(r, h - 1):
                    g[rr][partner] = color
        else:
            # Bottom-side marker: extend downward; translated line runs upward.
            partner = c + (top_start - bottom_start)
            for rr in range(r + 1, h - 1):
                g[rr][c] = color
            if 0 <= partner < w:
                for rr in range(1, r + 1):
                    g[rr][partner] = color

    for r, c, _ in markers:
        g[r][c] = 4
    return g
