 "content": "def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    counts = {}
    for row in g:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)

    def edge_span(row):
        cols = [c for c, value in enumerate(row) if value != background]
        return (min(cols), max(cols)) if cols else None

    top = edge_span(g[0])
    bottom = edge_span(g[-1])
    if top is None or bottom is None:
        return g
    top_start, top_end = top
    bottom_start, bottom_end = bottom

    markers = [(r, c, g[r][c]) for r in range(1, h - 1)
               for c in range(w) if g[r][c] != background]

    for r, c, color in markers:
        # Associate the point with whichever horizontal edge bar is nearest
        # in x. Continue its own column toward that edge.
        top_distance = max(top_start - c, 0, c - top_end)
        bottom_distance = max(bottom_start - c, 0, c - bottom_end)
        if top_distance <= bottom_distance:
            own_is_top = True
            partner = c + (bottom_start - top_start)
            for rr in range(1, r):
                g[rr][c] = color
        else:
            own_is_top = False
            partner = c + (top_start - bottom_start)
            for rr in range(r + 1, h - 1):
                g[rr][c] = color

        # The corresponding column at the opposite bar is filled throughout
        # the interior. Do not overwrite any original marker; all are changed
        # to 4 after the projections are drawn.
        if 0 <= partner < w:
            for rr in range(1, h - 1):
                g[rr][partner] = color

    for r, c, _ in markers:
        g[r][c] = 4
    return g
