 "content": "def transform(grid):
    """Project interior markers between the two offset bars at the top/bottom."""
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    counts = {}
    for row in g:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)

    def edge_bar(row):
        # Return the span of the repeated non-background run on an edge.
        runs = []
        c = 0
        while c < w:
            end = c + 1
            while end < w and row[end] == row[c]:
                end += 1
            if row[c] != background and end - c >= 3:
                runs.append((c, end - 1))
            c = end
        return max(runs, key=lambda run: run[1] - run[0]) if runs else None

    top = edge_bar(g[0])
    bottom = edge_bar(g[-1])
    if top is None or bottom is None:
        return g
    top_start, top_end = top
    bottom_start, bottom_end = bottom

    markers = [(r, c, g[r][c]) for r in range(1, h - 1)
               for c in range(w) if g[r][c] != background]

    for r, c, color in markers:
        # Associate each marker with the edge bar whose horizontal span is
        # nearest, then project it toward that edge and across to the other.
        top_dist = max(top_start - c, 0, c - top_end)
        bottom_dist = max(bottom_start - c, 0, c - bottom_end)
        if top_dist < bottom_dist:
            partner = c + (bottom_start - top_start)
            for rr in range(1, r):
                g[rr][c] = color
            if 0 <= partner < w:
                for rr in range(r + 1, h - 1):
                    g[rr][partner] = color
        else:
            partner = c + (top_start - bottom_start)
            for rr in range(r + 1, h - 1):
                g[rr][c] = color
            if 0 <= partner < w:
                for rr in range(1, r + 1):
                    g[rr][partner] = color

    for r, c, _ in markers:
        g[r][c] = 4
    return g
